  'title.menu': 'Menu principal',
  'title.campaign': 'CAMPAGNE',
  'title.inDev': 'EN DÉVELOPPEMENT',
  'title.campaignSub': 'L’opération Sweet Liberty, chapitre par chapitre. Votre progression est gardée dans ce navigateur',
