  'cine.chapter': 'OPÉRATION SWEET LIBERTY · CHAPITRE {n} : {name}',
  'cast.start': [
    'ktl|Chef Phantom au destroyer. Les Helldivers sont en approche finale et les SEAF tiennent jusqu’à leur atterrissage. Gardez la zone de largage propre.',
    'ktl|Ici KTL. Le général veut que ce soit rapide et bien fait. Dégagez la zone d’atterrissage, artilleur.',
  ],
  'cast.landed': [
    'rudolph|Tibit Tigers au sol ! Ça sent le sable chaud et les tripes d’insecte ici.',
    'rudolph|Rudolph the Red, bottes au sol. Montrez-nous une cible, artilleur, et gardez le ciel brûlant.',
    'rudolph|Les Tigers sont en bas et en colère. Beau largage, destroyer.',
  ],
  'cast.intel.bugs': [
    'neonboot|Ici le ministère de la Science. La souche Prédatrice chasse en meute et frappe depuis le couvert : frappez la meute, pas les traînards.',
    'neonboot|Analyse de la Science : carapace fine sur les petits, blindage sur les gros. Gardez les obus lourds pour les lourds.',
  ],
  'cast.intel.bots': [
    'neonboot|Ministère de la Science : la conduite de tir des Automates est bonne à distance et mauvaise contre les abris. Servez-vous des murs.',
    'neonboot|Ici la Science. Ces navettes amènent des escouades entières. Brûlez-les à l’arrivée et le combat rétrécit.',
  ],
  'cast.intel.squids': [
    'neonboot|Ministère de la Science : les boucliers illuminés absorbent les premiers coups. Arrachez-les, puis visez le corps.',
    'neonboot|Ici la Science. Les munitions légères usent toujours les boucliers illuminés. Gardez le canon sur eux.',
  ],
  'cast.heavy': [
    'neonboot|Contact lourd confirmé. Le ministère de la Science dit de viser les articulations et le dos.',
    'neonboot|F.E.A.R. signale un lourd sur le terrain. Antichar dessus, artilleur.',
  ],
  'cast.flare': [
    'neonboot|Ils ont tiré une fusée. D’autres arrivent : abattez le tireur si vous pouvez.',
    'neonboot|Fusée en l’air. Le ministère de la Science compte une navette pleine en approche.',
  ],
  'cast.boss': [
    'mota|Ici le ministère de la Défense. Super-lourd confirmé. Vous avez le feu vert pour tout ce que vous avez.',
    'mota|Chevalier de Minuit au destroyer : c’est un super-lourd. Le ministère le veut mort avant l’atterrissage du pélican.',
  ],
  'cast.bossDown': [
    'rudolph|Il est tombé ! Les Tigers ont tout vu. Magnifique.',
    'rudolph|Super-lourd abattu ! Que quelqu’un le peigne sur la coque du destroyer.',
  ],
  'cast.hdLost': [
    'rudolph|On en a perdu un ! Envoyez un renfort, les Tigers ne laissent personne derrière.',
    'rudolph|Helldiver à terre. Tibit Tigers, serrez les rangs et avancez.',
    'rudolph|Homme à terre ! Le suivant arrive. Gardez-les loin du largage.',
  ],
  'cast.livesLow': [
    'mota|Alerte du ministère de la Défense : il ne reste presque plus de renforts. Que chaque vie compte.',
    'ktl|Ici KTL. On en est aux derniers renforts. Protégez l’escouade.',
  ],
  'cast.seafLoss': [
    'mota|Les pertes des SEAF sont lourdes. Le ministère de la Défense vous demande de les garder à couvert.',
    'mota|La Défense compte vingt SEAF perdus. De braves soldats. Ne gaspillez pas les autres.',
  ],
  'cast.bigHit': [
    'rudolph|{n} d’un seul coup ! Mettez ça dans la brochure du complexe !',
    'rudolph|Ouah, {n} d’un coup ! Rappelez-moi de rester dans vos bonnes grâces, artilleur.',
    'rudolph|{n} éliminés en une frappe ! Les Tibit Tigers vous saluent.',
  ],
  'cast.side': [
    'mota|Objectif secondaire rempli. Le ministère de la Défense remarque ce genre de choses.',
    'mota|Bien. Une chose de moins pour l’ennemi. La Défense vous remercie.',
  ],
  'cast.objective': [
    'ktl|Objectif confirmé. Les Phantom préparent l’extraction.',
    'ktl|Objectif rempli. Maintenant, ramenez tout le monde.',
  ],
  'cast.general': [
    'ramzies|Ici Ramzies. Bien joué, Forces spéciales. Finissez proprement.',
    'ramzies|Ici le général. Voilà comment la Super-Terre fait les choses. Maintenant, ramenez-les.',
  ],
  'cast.extract': [
    'ktl|Pélican en approche. Tenez la plateforme jusqu’à son atterrissage.',
    'ktl|Extraction demandée. Dégagez la zone d’atterrissage, artilleur.',
  ],
  'cast.extractLive': [
    'rudolph|Le pélican est posé ! Tigers, à bord, on bouge, on bouge !',
    'rudolph|Le taxi est là ! Le dernier à bord paie la tournée !',
  ],
